            //
            aOrbiterE = ((aOrbiterE + aOrbiterH) + 0xF7971FC17E5984DAULL) + aTwistOrbiterUpdateSaltE[((aIndex + 83U)) & S_SALT1];
            aOrbiterJ = (aOrbiterJ ^ aOrbiterE) ^ 0x3BB95C7A97016DC8ULL;
