            //
            aCross = (RotL64(aIceLaneC[((S_BLOCK1 - aIndex + 7540U)) & S_BLOCK1], 5U) ^ RotL64(aIceLaneA[((S_BLOCK1 - aIndex + 3059U)) & S_BLOCK1], 29U));
            aCross ^= (RotL64(aEarthLaneD[((S_BLOCK1 - aIndex + 7495U)) & S_BLOCK1], 42U) ^ RotL64(pCrossLaneB[((aIndex + 2253U)) & S_BLOCK1], 57U));
            aCross = TwistMix64::DiffuseB((aCross ^ aTwistDomainWordCross));
            //
            aScatter = (RotL64(aCross, 53U) ^ RotL64(aIngress, 19U)) + (RotL64(aCarry, 41U) ^ RotL64(aPrevious, 6U));
            aScatter = TwistMix64::DiffuseB((aScatter ^ aTwistDomainWordScatter));
